std::map<std::string, int> word_count_c41b_1(const std::string& input) {
    std::map<std::string, int> count;
    std::string word;
    for (char c : input) {
        if (std::isalnum(c)) {
            word += std::tolower(c);
        } else if (!word.empty()) {
            count[word]++;
            word.clear();
        }
    }
    if (!word.empty()) {
        count[word]++;
    }
    return count;
}
